// Keep the original pre-simplification save available for its archived rules.
try{const original=localStorage.getItem('council-crown-before-v06');if(original){const button=document.createElement('button');button.textContent='Download save before v0.6';button.title='Use this original backup with its matching archived version.';button.onclick=()=>{const url=URL.createObjectURL(new Blob([original],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='council-crown-before-v06.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('.release-bar').append(button);}if(saveBlocked)notify('Autosave is paused to protect an earlier save. Download a backup, then open a valid campaign to resume saving.');}catch{}
